// 基础JSX
const element = <h1>Hello, React!</h1>;

// 嵌入表达式
const name = '小明';
const greeting = <h1>你好，{name}！</h1>;

// 表达式可以是函数调用
function formatName(user) {
  return user.firstName + ' ' + user.lastName;
}
const user = { firstName: '明', lastName: '李' };
const element2 = <h1>欢迎，{formatName(user)}！</h1>;

