// 可复用的小组件
function Button({ children, variant = 'primary', ...rest }) {
  const baseStyle = { padding: '8px 16px', border: 'none', borderRadius: '4px', cursor: 'pointer' };
  const variants = {
    primary: { ...baseStyle, backgroundColor: '#007bff', color: 'white' },
    danger: { ...baseStyle, backgroundColor: '#dc3545', color: 'white' },
    success: { ...baseStyle, backgroundColor: '#28a745', color: 'white' }
  };
  return <button style={variants[variant]} {...rest}>{children}</button>;
}

// 输入框组件
function Input({ label, id, ...rest }) {
  return (
    <div>
      {label && <label htmlFor={id}>{label}</label>}
      <input id={id} {...rest} />
    </div>
  );
}

// 用小组件组合成表单组件
function LoginForm({ onSubmit }) {
  const handleSubmit = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    onSubmit({
      username: formData.get('username'),
      password: formData.get('password')
    });
  };
  return (
    <form onSubmit={handleSubmit}>
      <Input label="用户名" id="username" name="username" type="text" />
      <Input label="密码" id="password" name="password" type="password" />
      <Button type="submit">登录</Button>
    </form>
  );
}

