import { useState } from 'react';

// 错误示例：连续加1只加了一次（因为异步+闭包）
function WrongCounter() {
  const [count, setCount] = useState(0);
  const addThree = () => {
    setCount(count + 1); // 这里的count还是0
    setCount(count + 1); // 这里的count还是0
    setCount(count + 1); // 这里的count还是0
    // 结果只加了1，不是3！
  };
  return (
    <div>
      <p>{count}</p>
      <button onClick={addThree}>+3（错误写法）</button>
    </div>
  );
}

// 正确写法：函数式更新
function CorrectCounter() {
  const [count, setCount] = useState(0);
  const addThree = () => {
    setCount(prev => prev + 1); // prev是最新的
    setCount(prev => prev + 1);
    setCount(prev => prev + 1);
    // 结果是加3，正确！
  };
  return (
    <div>
      <p>{count}</p>
      <button onClick={addThree}>+3（正确写法）</button>
    </div>
  );
}

// 状态更新是异步的
function AsyncDemo() {
