import { useState } from 'react';

// ❌ 错误：直接修改对象
function WrongObject() {
  const [user, setUser] = useState({ name: '小明', age: 20 });
  const badUpdate = () => {
    user.age = 21; // 直接修改了state！
    setUser(user); // 引用没变，不会重新渲染
  };
  // ...
}

// ✅ 正确：创建新对象
function CorrectObject() {
  const [user, setUser] = useState({ name: '小明', age: 20 });
  const goodUpdate = () => {
    setUser({ ...user, age: 21 }); // 新对象
  };
  // ...
}

// ❌ 错误：直接修改数组
function WrongArray() {
  const [list, setList] = useState([1, 2, 3]);
  const addItem = () => {
    list.push(4); // 直接修改原数组
    setList(list); // 引用没变
  };
  // ...
}

// ✅ 正确：返回新数组
function CorrectArray() {
  const [list, setList] = useState([1, 2, 3]);
  // 添加
  const addItem = () => setList([...list, 4]);
  // 删除（按索引）
  const removeItem = (index) => setList(list.filter((_, i) => i !== index));
  // 更新
  const updateItem = (index, newValue) => {
    setList(list.map((item, i) => i === index ? newValue : item));
  };
  // ...
}

