import { useState, useEffect } from 'react';

// 例1：每次渲染都执行（不传依赖数组）
function LogEveryRender() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    console.log('组件渲染了');
  }); // 没有依赖数组
  return <button onClick={() => setCount(count + 1)}>点击{count}</button>;
}

// 例2：只执行一次（空依赖数组）
function MountOnly() {
  const [data, setData] = useState(null);
  useEffect(() => {
    console.log('组件挂载了');
    fetch('/api/data').then(res => res.json()).then(setData);
  }, []); // 空数组，只执行一次
  return <div>{data ? JSON.stringify(data) : '加载中...'}</div>;
}

// 例3：依赖某个状态
function DependsOnCount() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('');
  useEffect(() => {
    console.log('count变了:', count);
    document.title = `计数：${count}`;
  }, [count]); // 只有count变化时才执行
  return (
    <div>
      <button onClick={() => setCount(count + 1)}>+1</button>
      <input value={name} onChange={e => setName(e.target.value)} />
    </div>
  );
}

// 例4：多个依赖项
function MultipleDeps() {
  const [userId, setUserId] = useState(1);
  const [type, setType] = useState('posts');
  const [data, setData] = useState([]);
  useEffect(() => {
    fetch(`https://jsonplaceholder.typicode.com/${type}?userId=${userId}`)
      .then(res => res.json())
      .then(setData);
  }, [userId, type]); // userId或type变化时重新请求
  return (
    <div>
      <select value={type} onChange={e => setType(e.target.value)}>
        <option value="posts">文章</option>
        <option value="albums">相册</option>
      </select>
      <button onClick={() => setUserId(userId + 1)}>下一个用户</button>
      <ul>{data.map(item => <li key={item.id}>{item.title}</li>)}</ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

// 例1：定时器（一定要清理！）
function Timer() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => {
      setSeconds(s => s + 1);
    }, 1000);
    // 清理函数：组件卸载时清除定时器
    return () => clearInterval(timer);
  }, []);
  return <p>已过 {seconds} 秒</p>;
}

// 例2：窗口resize事件监听
function WindowSize() {
  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight });
  useEffect(() => {
    const handleResize = () => {
      setSize({ width: window.innerWidth, height: window.innerHeight });
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  return <p>窗口大小：{size.width} × {size.height}</p>;
}

// 例3：取消fetch请求（AbortController）
function UserData({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    const controller = new AbortController();
    const fetchData = async () => {
      setLoading(true);
      try {
        const res = await fetch(`/api/users/${userId}`, {
          signal: controller.signal
        });
        const data = await res.json();
        setUser(data);
      } catch (err) {
        if (err.name !== 'AbortError') {
          console.error(err);
        }
      } finally {
        setLoading(false);
      }
    };
    fetchData();
    return () => controller.abort(); // 取消请求
  }, [userId]);
  return <div>{loading ? '加载中...' : user.name}</div>;
}

// 例4：订阅模式（如WebSocket）
function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);
  useEffect(() => {
    const socket = new WebSocket(`wss://chat.example.com/${roomId}`);
    socket.onmessage = (event) => {
      setMessages(prev => [...prev, event.data]);
    };
    return () => socket.close();
  }, [roomId]);
  return <div>{messages.map((m, i) => <p key={i}>{m}</p>)}</div>;
}

import { useState, useEffect, useRef } from 'react';

// 场景1：本地存储同步
function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue];
}

// 场景2：防抖搜索
function DebouncedSearch() {
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState([]);
  useEffect(() => {
    if (!keyword) { setResults([]); return; }
    const timer = setTimeout(() => {
      fetch(`/api/search?q=${keyword}`)
        .then(res => res.json())
        .then(setResults);
    }, 500);
    return () => clearTimeout(timer);
  }, [keyword]);
  return (
    <div>
      <input value={keyword} onChange={e => setKeyword(e.target.value)} />
      <ul>{results.map(r => <li key={r.id}>{r.name}</li>)}</ul>
    </div>
  );
}

// 场景3：操作DOM（聚焦输入框）
function AutoFocusInput() {
  const inputRef = useRef(null);
  useEffect(() => {
    inputRef.current.focus();
  }, []);
  return <input ref={inputRef} />;
}

// 场景4：修改文档标题
function PageTitle({ title }) {
  useEffect(() => {
    document.title = title;
  }, [title]);
  return null;
}

// 场景5：鼠标位置追踪
function MouseTracker() {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  useEffect(() => {
    const handleMouseMove = (e) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);
  return <p>鼠标位置：({position.x}, {position.y})</p>;
}

// 场景6：第三方库（以ECharts为例）
function Chart({ data }) {
  const chartRef = useRef(null);
  const chartInstance = useRef(null);
  useEffect(() => {
    chartInstance.current = echarts.init(chartRef.current);
    return () => chartInstance.current.dispose();
  }, []);
  useEffect(() => {
    chartInstance.current.setOption({
      xAxis: { type: 'category', data: data.map(d => d.name) },
      yAxis: { type: 'value' },
      series: [{ type: 'bar', data: data.map(d => d.value) }]
    });
  }, [data]);
  return <div ref={chartRef} style={{width: '400px', height: '300px'}} />;
}

