import { useState } from 'react';

// 注册表单示例（推荐写法：对象state + name属性）
function RegisterForm() {
  const [form, setForm] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    gender: 'male',
    agree: false
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);

  // 统一的change处理函数
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
    // 清除对应字段的错误
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  // 表单验证
  const validate = () => {
    const newErrors = {};
    if (!form.username.trim()) newErrors.username = '用户名不能为空';
    else if (form.username.length < 3) newErrors.username = '用户名至少3个字符';
    if (!form.email.trim()) newErrors.email = '邮箱不能为空';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) newErrors.email = '邮箱格式不正确';
    if (!form.password) newErrors.password = '密码不能为空';
    else if (form.password.length < 6) newErrors.password = '密码至少6位';
    if (form.password !== form.confirmPassword) newErrors.confirmPassword = '两次密码不一致';
    if (!form.agree) newErrors.agree = '请同意用户协议';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // 提交表单
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setLoading(true);
    try {
      await api.register(form);
      alert('注册成功！');
      // 重置表单
      setForm({
        username: '', email: '', password: '',
        confirmPassword: '', gender: 'male', agree: false
      });
    } catch (err) {
      setErrors({ submit: err.message });
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{maxWidth: '400px', margin: '0 auto'}}>
      <h2>用户注册</h2>
      {errors.submit && <p style={{color:'red'}}>{errors.submit}</p>}

      <div>
        <label>用户名：</label>
        <input name="username" value={form.username} onChange={handleChange} />
        {errors.username && <span style={{color:'red'}}>{errors.username}</span>}
      </div>

      <div>
        <label>邮箱：</label>
        <input name="email" type="email" value={form.email} onChange={handleChange} />
        {errors.email && <span style={{color:'red'}}>{errors.email}</span>}
      </div>

      <div>
        <label>密码：</label>
        <input name="password" type="password" value={form.password} onChange={handleChange} />
        {errors.password && <span style={{color:'red'}}>{errors.password}</span>}
      </div>

      <div>
        <label>确认密码：</label>
        <input name="confirmPassword" type="password" value={form.confirmPassword} onChange={handleChange} />
        {errors.confirmPassword && <span style={{color:'red'}}>{errors.confirmPassword}</span>}
      </div>

      <div>
        <label>性别：</label>
        <label><input name="gender" type="radio" value="male" checked={form.gender==='male'} onChange={handleChange} />男</label>
        <label><input name="gender" type="radio" value="female" checked={form.gender==='female'} onChange={handleChange} />女</label>
      </div>

      <div>
        <label>
          <input name="agree" type="checkbox" checked={form.agree} onChange={handleChange} />
          同意用户协议
        </label>
        {errors.agree && <span style={{color:'red'}}>{errors.agree}</span>}
      </div>

      <button type="submit" disabled={loading}>
        {loading ? '注册中...' : '注册'}
      </button>
    </form>
  );
}

