      <button onClick={() => dispatch({ type: 'decrement' })}>-1</button>
      <button onClick={() => dispatch({ type: 'reset' })}>重置</button>
      <button onClick={() => dispatch({ type: 'incrementBy', payload: 5 })}>+5</button>
    </div>
  );
}

// 例2：待办事项列表（更复杂的状态）
const todosInitialState = { todos: [], filter: 'all' };

function todosReducer(state, action) {
  switch (action.type) {
    case 'ADD_TODO':
      return {
        ...state,
        todos: [...state.todos, {
          id: Date.now(),
          text: action.payload,
          done: false
        }]
      };
    case 'TOGGLE_TODO':
      return {
        ...state,
        todos: state.todos.map(todo =>
          todo.id === action.payload ? { ...todo, done: !todo.done } : todo
        )
      };
    case 'DELETE_TODO':
      return {
        ...state,
        todos: state.todos.filter(todo => todo.id !== action.payload)
      };
    case 'SET_FILTER':
      return { ...state, filter: action.payload };
    default:
      return state;
  }
}

function TodoApp() {
  const [state, dispatch] = useReducer(todosReducer, todosInitialState);
  const { todos, filter } = state;

  const [text, setText] = React.useState('');

  const addTodo = () => {
    if (text.trim()) {
      dispatch({ type: 'ADD_TODO', payload: text });
      setText('');
    }
  };

  const filteredTodos = todos.filter(todo => {
    if (filter === 'active') return !todo.done;
    if (filter === 'completed') return todo.done;
    return true;
  });

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <button onClick={addTodo}>添加</button>

      <div>
        <button onClick={() => dispatch({ type: 'SET_FILTER', payload: 'all' })}>全部</button>
        <button onClick={() => dispatch({ type: 'SET_FILTER', payload: 'active' })}>未完成</button>
        <button onClick={() => dispatch({ type: 'SET_FILTER', payload: 'completed' })}>已完成</button>
      </div>

      <ul>
        {filteredTodos.map(todo => (
          <li key={todo.id} style={{textDecoration: todo.done ? 'line-through' : 'none'}}>
            <span onClick={() => dispatch({ type: 'TOGGLE_TODO', payload: todo.id })}>
              {todo.text}
            </span>
            <button onClick={() => dispatch({ type: 'DELETE_TODO', payload: todo.id })}>删除</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

