import { useState, useMemo, useCallback, memo } from 'react';

// useMemo：缓存复杂计算结果
function ExpensiveComputation() {
  const [count, setCount] = useState(0);
  const [todos, setTodos] = useState([]);

  // 昂贵的计算（每次渲染都会执行，没有useMemo的话）
  const expensiveValue = useMemo(() => {
    console.log('计算中...');
    let result = 0;
    for (let i = 0; i < 1000000; i++) {
      result += i;
    }
    return result + count;
  }, [count]); // 只有count变化时才重新计算

  return (
    <div>
      <p>计算结果：{expensiveValue}</p>
      <button onClick={() => setCount(count + 1)}>count+1（触发重计算）</button>
      <button onClick={() => setTodos([...todos, 'new'])}>添加todo（不触发重计算）</button>
      <p>todos数量：{todos.length}</p>
    </div>
  );
}

