  const { user } = useAuth();
  const location = useLocation();

  if (!user) {
    // 未登录，重定向到登录页，并记录来源地址
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return children;
}

// 角色守卫组件
function RequireRole({ role, children }) {
  const { user } = useAuth();

  if (!user) {
    return <Navigate to="/login" replace />;
