import { combineReducers } from 'redux';

// Action Types
const ADD_TODO = 'ADD_TODO';
const TOGGLE_TODO = 'TOGGLE_TODO';
const DELETE_TODO = 'DELETE_TODO';
const SET_FILTER = 'SET_FILTER';

// Action Creators
const addTodo = (text) => ({ type: ADD_TODO, payload: text });
const toggleTodo = (id) => ({ type: TOGGLE_TODO, payload: id });
const deleteTodo = (id) => ({ type: DELETE_TODO, payload: id });
const setFilter = (filter) => ({ type: SET_FILTER, payload: filter });

// Reducers
function todosReducer(state = [], action) {
  switch (action.type) {
    case ADD_TODO:
      return [...state, { id: Date.now(), text: action.payload, completed: false }];
    case TOGGLE_TODO:
      return state.map(todo =>
        todo.id === action.payload ? { ...todo, completed: !todo.completed } : todo
      );
    case DELETE_TODO:
      return state.filter(todo => todo.id !== action.payload);
    default:
      return state;
  }
}

function filterReducer(state = 'all', action) {
  switch (action.type) {
    case SET_FILTER:
      return action.payload;
    default:
      return state;
  }
}

// 合并reducer
const rootReducer = combineReducers({
  todos: todosReducer,
  filter: filterReducer
});

const todoStore = createStore(rootReducer);

// 组件
function TodoApp() {
  const todos = useSelector(state => state.todos);
  const filter = useSelector(state => state.filter);
  const dispatch = useDispatch();
  const [text, setText] = React.useState('');

  const filteredTodos = todos.filter(todo => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  const handleAdd = () => {
    if (text.trim()) {
      dispatch(addTodo(text));
      setText('');
    }
  };

  return (
    <Provider store={todoStore}>
      <div>
        <input value={text} onChange={e => setText(e.target.value)} />
        <button onClick={handleAdd}>添加</button>

        <div>
          <button onClick={() => dispatch(setFilter('all'))}>全部</button>
          <button onClick={() => dispatch(setFilter('active'))}>未完成</button>
          <button onClick={() => dispatch(setFilter('completed'))}>已完成</button>
        </div>

        <ul>
          {filteredTodos.map(todo => (
            <li key={todo.id}>
              <span 
                onClick={() => dispatch(toggleTodo(todo.id))}
                style={{textDecoration: todo.completed ? 'line-through' : 'none'}}
              >
                {todo.text}
              </span>
