// 1. createSlice 创建 slice（reducer + actions 一起创建）
const counterSlice = createSlice({
  name: 'counter', // slice名称
  initialState: { count: 0 }, // 初始状态
  reducers: {
    // 可以直接"修改"状态（immer内部处理了不可变）
    increment(state) {
      state.count += 1;
    },
    decrement(state) {
      state.count -= 1;
    },
    incrementBy(state, action) {
      state.count += action.payload;
    },
    reset(state) {
      state.count = 0;
    }
  }
});

// 导出actions
const { increment, decrement, incrementBy, reset } = counterSlice.actions;

// 2. configureStore 创建 store
const store = configureStore({
  reducer: {
    counter: counterSlice.reducer
    // 可以加更多slice
  }
});

// 3. 组件中使用
