  if (loading) return <p>加载中...</p>;
  if (error) return <p style={{color: 'red'}}>错误：{error}</p>;

  return (
    <div>
      <h1>用户列表</h1>
      <ul>
        {users.map(user => (
          <li key={user.id}>
            {user.name} - {user.email}
          </li>
        ))}
      </ul>
    </div>
  );
}

