import TodoHeader from './components/TodoHeader';
import TodoList from './components/TodoList';
import TodoFooter from './components/TodoFooter';
import useLocalStorage from './hooks/useLocalStorage';
import './App.css';

function App() {
  // 用自定义Hook管理待办列表，自动同步localStorage
  const [todos, setTodos] = useLocalStorage('react-todos', []);
  const [filter, setFilter] = useState('all'); // all / active / completed

  // 添加待办
  const addTodo = useCallback((text) => {
    if (!text.trim()) return;
    setTodos(prev => [
      ...prev,
      {
        id: Date.now(),
        text: text.trim(),
        completed: false,
        createdAt: new Date().toISOString()
      }
    ]);
  }, [setTodos]);

  // 切换完成状态
  const toggleTodo = useCallback((id) => {
    setTodos(prev => prev.map(todo =>
      todo.id === id ? { ...todo, completed: !todo.completed } : todo
    ));
  }, [setTodos]);

  // 删除待办
  const deleteTodo = useCallback((id) => {
    setTodos(prev => prev.filter(todo => todo.id !== id));
  }, [setTodos]);

  // 编辑待办
  const editTodo = useCallback((id, newText) => {
    if (!newText.trim()) {
      // 文字为空就删除
      setTodos(prev => prev.filter(todo => todo.id !== id));
    } else {
      setTodos(prev => prev.map(todo =>
        todo.id === id ? { ...todo, text: newText.trim() } : todo
      ));
    }
  }, [setTodos]);

  // 清除已完成
  const clearCompleted = useCallback(() => {
    setTodos(prev => prev.filter(todo => !todo.completed));
  }, [setTodos]);

  // 全选/取消全选
  const toggleAll = useCallback(() => {
    setTodos(prev => {
      const allCompleted = prev.every(todo => todo.completed);
      return prev.map(todo => ({ ...todo, completed: !allCompleted }));
    });
  }, [setTodos]);

  // 过滤后的列表（用useMemo缓存）
  const filteredTodos = useMemo(() => {
    switch (filter) {
      case 'active':
        return todos.filter(todo => !todo.completed);
      case 'completed':
        return todos.filter(todo => todo.completed);
      default:
        return todos;
    }
  }, [todos, filter]);

  // 未完成数量
  const remainingCount = useMemo(
    () => todos.filter(todo => !todo.completed).length,
    [todos]
  );

  // 是否已全部完成
  const allCompleted = useMemo(
    () => todos.length > 0 && todos.every(todo => todo.completed),
    [todos]
  );

  return (
    <div className="todo-app">
      <h1 className="app-title">Todos</h1>
      <div className="todo-container">
        <TodoHeader onAdd={addTodo} />

        {todos.length > 0 && (
          <>
            <label className="toggle-all">
              <input 
                type="checkbox" 
                checked={allCompleted}
                onChange={toggleAll}
              />
              全选
            </label>
            <TodoList 
              todos={filteredTodos}
              onToggle={toggleTodo}
              onDelete={deleteTodo}
              onEdit={editTodo}
            />
            <TodoFooter 
              remaining={remainingCount}
              filter={filter}
              onFilterChange={setFilter}
              onClearCompleted={clearCompleted}
              hasCompleted={todos.some(t => t.completed)}
            />
          </>
        )}
      </div>
      <p className="app-footer">双击编辑待办事项</p>
    </div>
  );
}

export default App;

