import { useState } from 'react';

function TodoHeader({ onAdd }) {
  const [text, setText] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (text.trim()) {
      onAdd(text);
      setText('');
    }
  };

  return (
    <header className="todo-header">
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          className="new-todo"
          placeholder="需要做什么？"
          value={text}
          onChange={(e) => setText(e.target.value)}
          autoFocus
        />
        <button type="submit" className="add-btn">
          添加
        </button>
      </form>
    </header>
  );
}

export default TodoHeader;

// ========== src/components/TodoList.jsx ==========
import TodoItem from './TodoItem';

function TodoList({ todos, onToggle, onDelete, onEdit }) {
  if (todos.length === 0) {
    return <div className="empty-state">暂无待办事项</div>;
  }

  return (
    <ul className="todo-list">
      {todos.map(todo => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onToggle={() => onToggle(todo.id)}
          onDelete={() => onDelete(todo.id)}
          onEdit={(newText) => onEdit(todo.id, newText)}
        />
      ))}
    </ul>
  );
}

export default TodoList;

// ========== src/components/TodoItem.jsx ==========
import { useState, useRef, useEffect } from 'react';

function TodoItem({ todo, onToggle, onDelete, onEdit }) {
  const [editing, setEditing] = useState(false);
  const [editText, setEditText] = useState(todo.text);
  const inputRef = useRef(null);

  // 进入编辑状态时自动聚焦
  useEffect(() => {
    if (editing) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [editing]);

  // 双击进入编辑
  const handleDoubleClick = () => {
    setEditing(true);
    setEditText(todo.text);
  };

  // 提交编辑
  const handleSubmit = (e) => {
    e.preventDefault();
    onEdit(editText);
    setEditing(false);
  };

  // 按ESC取消编辑
  const handleKeyDown = (e) => {
    if (e.key === 'Escape') {
      setEditText(todo.text);
      setEditing(false);
    }
  };

  // 失去焦点也提交
  const handleBlur = () => {
    if (editing) {
      onEdit(editText);
      setEditing(false);
    }
  };

  return (
    <li className={`todo-item ${todo.completed ? 'completed' : ''} ${editing ? 'editing' : ''}`}>
      <div className="view">
        <input
          type="checkbox"
          className="toggle"
          checked={todo.completed}
          onChange={onToggle}
        />
        <label onDoubleClick={handleDoubleClick}>
          {todo.text}
        </label>
        <button className="destroy" onClick={onDelete}>×</button>
      </div>
      {editing && (
        <input
          ref={inputRef}
          type="text"
          className="edit-input"
          value={editText}
          onChange={(e) => setEditText(e.target.value)}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          onSubmit={handleSubmit}
        />
      )}
    </li>
  );
}

export default TodoItem;

// ========== src/components/TodoFooter.jsx ==========
function TodoFooter({ remaining, filter, onFilterChange, onClearCompleted, hasCompleted }) {
  return (
    <footer className="todo-footer">
      <span className="todo-count">
        <strong>{remaining}</strong> 项未完成
      </span>

      <ul className="filters">
        <li>
          <button
            className={filter === 'all' ? 'selected' : ''}
            onClick={() => onFilterChange('all')}
          >
            全部
          </button>
        </li>
        <li>
          <button
            className={filter === 'active' ? 'selected' : ''}
            onClick={() => onFilterChange('active')}
          >
            未完成
          </button>
        </li>
        <li>
          <button
            className={filter === 'completed' ? 'selected' : ''}
            onClick={() => onFilterChange('completed')}
          >
            已完成
          </button>
        </li>
      </ul>

      {hasCompleted && (
        <button className="clear-completed" onClick={onClearCompleted}>
          清除已完成
        </button>
      )}
    </footer>
  );
}

export default TodoFooter;

