// 1. React.memo - 组件记忆
const ExpensiveComponent = memo(function ExpensiveComponent({ data, onClick }) {
  console.log('ExpensiveComponent 渲染了');
  // 复杂的渲染...
  return (
    <div onClick={onClick}>
      {data.map(item => <div key={item.id}>{item.name}</div>)}
    </div>
  );
});

function Parent() {
  const [count, setCount] = useState(0);
  const [items] = useState([{ id: 1, name: 'item1' }]);

  // 用useCallback缓存函数，避免每次传新函数导致子组件重渲染
  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []);

  return (
    <div>
      <button onClick={() => setCount(count + 1)}>父组件计数: {count}</button>
      {/* count变化不会导致ExpensiveComponent重渲染 */}
      <ExpensiveComponent data={items} onClick={handleClick} />
    </div>
  );
}

// 2. useMemo - 缓存计算结果
function SearchResults({ items, keyword }) {
  // 过滤和排序是昂贵的计算，用useMemo缓存
  const filteredSortedItems = useMemo(() => {
    console.log('计算过滤和排序');
    return items
      .filter(item => item.name.includes(keyword))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [items, keyword]); // 依赖变化才重新计算

  return (
    <ul>
      {filteredSortedItems.map(item => (
        <li key={item.id}>{item.name}</li>
      ))}
    </ul>
  );
}

// 3. 状态下放 - 把状态移到真正需要它的子组件
